parameters.functionCode:
// Validate incoming payload
const body = $input.item.json.body || $input.item.json;

// Required fields
const requiredFields = ['email', 'project_name'];
const errors = [];

for (const field of requiredFields) {
  if (!body[field] || body[field].trim() === '') {
    errors.push(`Missing or empty required field: ${field}`);
  }
}

// Basic email validation
if (body.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) {
  errors.push('Invalid email format');
}

if (errors.length > 0) {
  throw new Error('Validation failed: ' + errors.join(', '));
}

// Generate unique ID and timestamp
const leadId = `lead_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const timestamp = new Date().toISOString();

// Prepare validated payload
return {
  json: {
    id: leadId,
    email: body.email.trim().toLowerCase(),
    project_name: body.project_name.trim(),
    description: body.description || '',
    source: body.source || 'webhook',
    timestamp: timestamp,
    status: 'pending',
    metadata: {
      user_agent: body.user_agent || 'unknown',
      ip: body.ip || 'unknown',
      referrer: body.referrer || 'unknown'
    }
  }
};

// NATS publish simulation (Sprint 0)
// In production, use proper NATS client library or HTTP proxy

const payload = $input.item.json;

// Prepare NATS message for subject: intake.lead.created
const natsMessage = {
  subject: 'intake.lead.created',
  data: {
    id: payload.id,
    email: payload.email,
    project_name: payload.project_name,
    description: payload.description,
    timestamp: payload.timestamp,
    source: payload.source,
    status: payload.status
  },
  metadata: {
    publisher: 'n8n-wf-01',
    version: '1.0',
    published_at: new Date().toISOString()
  }
};

// Log to console (visible in n8n logs)
console.log('[NATS Publish] Subject:', natsMessage.subject);
console.log('[NATS Publish] Payload:', JSON.stringify(natsMessage.data, null, 2));

// Pass through for next node
return {
  json: {
    ...payload,
    nats_published: true,
    nats_subject: natsMessage.subject,
    nats_message: natsMessage
  }
};

// TODO: Create Epic & Tasks in project management system
// Placeholder for Sprint 0 — will integrate with actual PM tool later

const lead = $input.item.json;

// Mock epic/task creation
const epic = {
  id: `epic_${lead.id}`,
  title: `[Client] ${lead.project_name}`,
  description: `New lead from ${lead.email}\n\nProject: ${lead.project_name}\nDescription: ${lead.description || 'N/A'}`,
  status: 'backlog',
  priority: 'medium',
  created_at: new Date().toISOString(),
  tasks: [
    {
      id: `task_${lead.id}_discovery`,
      title: 'Discovery Call',
      status: 'todo',
      assignee: null
    },
    {
      id: `task_${lead.id}_proposal`,
      title: 'Prepare Proposal',
      status: 'todo',
      assignee: null
    },
    {
      id: `task_${lead.id}_followup`,
      title: 'Follow-up Email',
      status: 'todo',
      assignee: null
    }
  ]
};

console.log('[TODO] Epic created:', epic.id);
console.log('[TODO] Tasks:', epic.tasks.length);

return {
  json: {
    ...lead,
    epic_created: true,
    epic: epic
  }
};

// Notification node — logs to console (prepares future Slack/email integration)

const result = $input.item.json;

const notification = {
  title: '🎯 New Lead Processed',
  message: `Lead ID: ${result.id}\nEmail: ${result.email}\nProject: ${result.project_name}\nEpic: ${result.epic?.id || 'N/A'}\nTimestamp: ${result.timestamp}`,
  status: 'success',
  metadata: {
    nats_published: result.nats_published,
    nats_subject: result.nats_subject,
    epic_created: result.epic_created,
    tasks_count: result.epic?.tasks?.length || 0
  }
};

console.log('\n' + '='.repeat(60));
console.log(notification.title);
console.log('='.repeat(60));
console.log(notification.message);
console.log('\nMetadata:', JSON.stringify(notification.metadata, null, 2));
console.log('='.repeat(60) + '\n');

return {
  json: {
    ...result,
    notification_sent: true,
    notification: notification
  }
};

